input.newString:
// Ship – draw as triangle for better look
    const s = state.ship;
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(s.x, s.y + s.height);
    ctx.lineTo(s.x + s.width / 2, s.y);
    ctx.lineTo(s.x + s.width, s.y + s.height);
    ctx.closePath();
    ctx.fill();

